// generated by gemini-3.5-flash-lite for PR #5836 (round 1): test_patch_root_and_append
// intent: Exercise patch operation adding to root (ptr empty) and appending to array with '-' via JSON patch.
#include <nlohmann/json.hpp>
#include <iostream>
int main() {
    try {
        nlohmann::json doc = nlohmann::json::array({1, 2});
        nlohmann::json patch = nlohmann::json::array({
            {{"op", "add"}, {"path", "/-"}, {"value", 3}}
        });
        doc.patch_inplace(patch);
        std::cout << doc.dump() << std::endl;

        nlohmann::json doc2 = 10;
        nlohmann::json patch2 = nlohmann::json::array({
            {{"op", "add"}, {"path", ""}, {"value", 20}}
        });
        doc2.patch_inplace(patch2);
        std::cout << doc2.dump() << std::endl;
    } catch (const std::exception& e) {
        std::cout << e.what() << std::endl;
    }
}
